/// <summary>
/// MPJ_5012_RebateProcess
/// </summary>
[
    DataContractAttribute,
    SysOperationGroup('Period', literalstr("@RebatesAndDeductions:Period"), '1'),
    SysOperationGroup('Transaction', literalstr("@SYS15191"), '2', FormArrangeMethod::Vertical)
]
class METRebateExternalDataSourceContract implements SysOperationValidatable
{
    FromDate                    fromTransDate;
    ToDate                      toTransDate;
    TAMRebateDeal               rebateDeal;
    TAMRebateTransactionType    transType;
    Qty                         toleranceQty;

}

Method.Source:
/// <summary>
/// MPJ_5012_RebateProcess
/// parameter to set the Transaction From date
/// </summary>
/// <param name = "_fromTransDate"> Transaction from date </param>
/// <returns>fromTransDate</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute("@SYS5209"),
    SysOperationGroupMemberAttribute("@RebatesAndDeductions:Period"),
    SysOperationDisplayOrderAttribute('1'),
    AifCollectionTypeAttribute('return', Types::Date)
]
public FromDate parmFromTransDate(FromDate _fromTransDate = fromTransDate)
{
    fromTransDate = _fromTransDate;
    return fromTransDate;
}

/// <summary>
/// MPJ_5012_RebateProcess
/// parameter to set the Transaction To date
/// </summary>
/// <param name = "_toTransDate"> Transaction to date </param>
/// <returns>toTransDate</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute("@SYS312576"),
    SysOperationGroupMemberAttribute("@RebatesAndDeductions:Period"),
    SysOperationDisplayOrderAttribute('2'),
    AifCollectionTypeAttribute('return', Types::Date)
]
public ToDate parmToTransDate(ToDate _toTransDate = toTransDate)
{
    toTransDate = _toTransDate;
    return toTransDate;
}

/// <summary>
/// MPJ_5012_RebateProcess
/// parameter to set the Transaction type
/// </summary>
/// <param name = "_transType"> Transaction type </param>
/// <returns>transType</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute("@SYS480"),
    SysOperationGroupMemberAttribute("@SYS15191"),
    SysOperationDisplayOrderAttribute('1')
]
public TAMRebateTransactionType parmTransType(TAMRebateTransactionType _transType = transType)
{
    transType = _transType;
    return transType;
}

/// <summary>
/// MPJ_5012_RebateProcess
/// parameter to set the Tolerance quantity
/// </summary>
/// <param name = "_toleranceQty"> Tolerance quantity </param>
/// <returns>toleranceQty</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute("@MET:ToleranceQuantity"),
    SysOperationGroupMemberAttribute("@SYS15191"),
    SysOperationDisplayOrderAttribute('2'),
    AifCollectionTypeAttribute('return', Types::Real)
]
public Qty parmToleranceQty(Qty _toleranceQty = toleranceQty)
{
    toleranceQty = _toleranceQty;
    return toleranceQty;
}

[DataMemberAttribute, SysOperationControlVisibility(false)]
public TAMRebateDeal parmTAMRebateDeal(TAMRebateDeal _rebateDeal = rebateDeal)
{
    rebateDeal = _rebateDeal;
    return rebateDeal;
}

    /// <summary>
    /// MPJ_5012_RebateProcess
    /// </summary>
    /// <returns> isValid true or false </returns>
    public boolean validate()
    {
        boolean isValid = true;

        if(fromTransDate > toTransDate)
        {
            isValid = checkFailed("@MET:IncorrectDates");
        }

        return isValid;
    }
